package aoc2015.day15

/** Shared helpers that turn a list of ingredients and an allocation of teaspoons into a cookie
  * score.
  */

/** The exact number of teaspoons a recipe must use, split across all ingredients. */
val teaspoons: Int = 100

/** Every way to split `total` into `count` non-negative whole-teaspoon amounts.
  *
  * The result is a sequence of amounts, one entry per ingredient, in which every entry is a
  * non-negative integer and all entries sum to `total`. The lists are generated by recursing over
  * the first amount and delegating the remainder to fewer parts, so `count` must be at least one.
  */
def compositions(count: Int, total: Int): Seq[Seq[Int]] =
  if count == 1 then Seq(Seq(total))
  else
    for
      first <- 0 to total
      rest <- compositions(count - 1, total - first)
    yield first +: rest
  end if
end compositions

/** The score of combining the ingredients using the given per-ingredient teaspoon amounts.
  *
  * Each property total sums `amount * property` across all ingredients and floors negative totals
  * to zero. The score multiplies the four non-calorie property totals, so a single non-positive
  * total makes the whole cookie score zero.
  */
def score(ingredients: Seq[Ingredient], amounts: Seq[Int]): Int =
  val capacity = ingredients.zip(amounts).map((ingredient, amount) => amount * ingredient.capacity)
    .sum
  val durability = ingredients.zip(amounts)
    .map((ingredient, amount) => amount * ingredient.durability).sum
  val flavor = ingredients.zip(amounts).map((ingredient, amount) => amount * ingredient.flavor).sum
  val texture = ingredients.zip(amounts).map((ingredient, amount) => amount * ingredient.texture)
    .sum
  capacity.max(0) * durability.max(0) * flavor.max(0) * texture.max(0)
end score
